import { Schema as S } from "effect";
import type { Command } from "foldkit";
import { Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import * as RadioGroup from "../../ui/shadcn-radio-group";

// MODEL

export const Model = S.Struct({});
export type Model = typeof Model.Type;

// MESSAGE

export const Message = S.Never;
export type Message = typeof Message.Type;

// INIT

export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => [{}, []];

// UPDATE

export const update = (
  model: Model,
  _message: Message
): readonly [Model, readonly Command.Command<Message>[]] => [model, []];

// VIEW

const cardView = (
  value: string,
  description: string,
  selected: boolean
): Html => {
  const h = html<Message>();

  return h.div(
    [
      h.Class(
        "flex min-w-56 items-start gap-3 rounded-md border border-gray-200 p-4"
      ),
    ],
    [
      h.button(
        [
          h.Type("button"),
          h.Role("radio"),
          h.AriaChecked(selected),
          h.AriaLabel(value),
          h.Class("mt-0.5"),
        ],
        [selected ? RadioGroup.checkIcon() : RadioGroup.checkPlaceholder()]
      ),
      h.div(
        [h.Class(RadioGroup.shadcnRadioGroupMetaClasses)],
        [
          h.span([h.Class(RadioGroup.shadcnRadioGroupLabelClasses)], [value]),
          h.p(
            [h.Class(RadioGroup.shadcnRadioGroupDescriptionClasses)],
            [description]
          ),
        ]
      ),
    ]
  );
};

export const view = Submodel.defineView<Model, Message>((): Html => {
  const h = html<Message>();

  return h.div(
    [
      h.Role("radiogroup"),
      h.AriaLabel("Plan"),
      h.Class("grid gap-3 sm:grid-cols-3"),
    ],
    [
      cardView("Plus", "For individuals and small teams.", true),
      cardView("Pro", "For growing businesses.", false),
      cardView("Enterprise", "For large teams and enterprises.", false),
    ]
  );
});

import { Scene } from "foldkit";
import { describe, test } from "vitest";

import * as Example from "./main";

describe("shadcn Radio Group Choice Card example", () => {
  test("renders the origin card-style selection demo", () => {
    Scene.scene(
      { update: Example.update, view: Example.view },
      Scene.with(Example.init()[0]),
      Scene.expect(Scene.role("radiogroup", { name: "Plan" })).toExist(),
      Scene.expect(Scene.role("radio", { name: "Plus" })).toBeChecked(),
      Scene.expect(Scene.role("radio", { name: "Plus" })).not.toHaveHandler(
        "click"
      ),
      Scene.expect(Scene.role("radio", { name: "Pro" })).not.toBeChecked(),
      Scene.expect(Scene.text("For large teams and enterprises.")).toExist()
    );
  });
});
